  "claim": {
    "component_id": "C010.component",
    "value": "If a bounded experiment is unavailable, the deployment choice should supply the necessary controls and comparable telemetry.",
    "scope": "Conditional preparatory deployment decision, with the perturbation deferred.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly supplies the conditional deployment recommendation and its accompanying deferral."
    }
  },
  "signal_basis": {
    "component_id": "C010.signal_basis",
    "value": "The proposed test requires adjustable concurrency, a safely bounded canary pool, and comparable timing measurements. When bounded experimentation is unavailable, defer the perturbation and supply the necessary controls and telemetry; missing timestamps call for instrumentation and an overnight baseline before performance testing.",
    "scope": "Preparation for the proposed experiment. This branch requires no observed transient response and makes no claim of measured performance benefit.",
    "provenance": {
      "refs": [
        {
          "source_id": "P003",
          "role": "SUPPORT"
        },
